		el := float64(snap.EffectiveLoad())
		excess := el - minLoad

		// Adaptive exponential load decay - stronger penalty during high imbalance
		loadMult := 1.0
		if excess > 0.0 {
			effectiveDecay := loadDecay
			// Increase penalty when cluster is imbalanced (load spikes)
			if loadSpread > 3.0 {
				imbalanceFactor := (loadSpread - 3.0) * 0.05
				if imbalanceFactor > 0.2 { imbalanceFactor = 0.2 }
				effectiveDecay += imbalanceFactor
